import java.io.*;import java.nio.file.*;import java.util.*;import java.security.*;import com.alibaba.fastjson2.*;import webridge.wbridge.storedprocedure.SPDefinition;
public class VerifySpDef{static String hash(byte[]b)throws Exception{StringBuilder s=new StringBuilder();for(byte x:MessageDigest.getInstance("SHA-256").digest(b))s.append(String.format("%02x",x&255));return s.toString();}public static void main(String[]a)throws Exception{Path p=Paths.get(a[0]);try(ObjectInputStream in=new ObjectInputStream(new BufferedInputStream(Files.newInputStream(p)))){Object value=in.readObject();List<SPDefinition> defs=(List<SPDefinition>)value;JSONArray rows=new JSONArray();for(SPDefinition d:defs){Path sql=p.getParent().resolve("graph-SP-"+d.getSpName()+".sql");byte[] generated=Files.readAllBytes(sql);if(d.getSpSQL()!=null)throw new IllegalStateException("Expected source-declared transient SQL field");if(!new String(generated,"UTF-8").contains(d.getSpName()))throw new IllegalStateException("Procedure name missing from emitted SQL");JSONObject r=new JSONObject();r.put("api",d.getApiName());r.put("procedure",d.getSpName());r.put("sql_file",sql.toString());r.put("sql_bytes",generated.length);r.put("sql_sha256",hash(generated));r.put("serialized_SQL_is_source_declared_transient",true);r.put("serialized_definition_procedure_matches_SQL_file",true);r.put("call_statement",d.getCallSpStatement());rows.add(r);}JSONObject r=new JSONObject();r.put("deserialization_ok",true);r.put("definition_count",defs.size());r.put("definition_sha256",hash(Files.readAllBytes(p)));r.put("definitions",rows);System.out.println(r.toJSONString());}}
}
